const SECTIONS={def:"Definitions",sup:"Superiority & movement",to:"Train orders",sig:"Signals & whistles",sem:"Semaphores",yl:"Yard limits",twc:"Track warrants",gcor:"GCOR crew & speed"};
const SRC={SC:"§1.0 Standard Code",GC:"§1.1 GCOR",TT:"§2 TT&TO primer",YL:"§3 Yard Limits",TW:"§4 Track Warrants",SG:"§5 Signals",SM:"§6 Semaphores"};
const CARDS=[];const QS=[];
function C(s,f,b,src,note,fig){CARDS.push({s,f,b,src,note,fig})}
function Q(s,q,opts,why,src,fig){QS.push({s,q,opts,why,src,fig})}
const figHtml=f=>f?`<div class="ce-fig">${sigFig(f)}</div>`:"";

/* ---------- FLASHCARDS ---------- */
// Definitions (Standard Code, red)
C("def","Regular train","A train authorized by time-table schedule.","SC · Definitions");
C("def","Extra train","A train not authorized by a time-table schedule. Designated as:\n• Extra: any extra except passenger extra or work extra\n• Passenger Extra: passenger train extra\n• Work Extra: work train extra","SC · Definitions");
C("def","Time-table","The authority for the movement of regular trains subject to the rules. It contains classified schedules with special instructions relating to the movement of trains.","SC · Definitions");
C("def","Schedule","That part of a time-table which prescribes class, direction, number and movement for a regular train.","SC · Definitions");
C("def","Time-table vs. schedule: what is the difference?","The time-table (sometimes called an Employee Time-Table or “ETT”) is often in book or pamphlet form. It holds the authority for the movement of regular trains, the classified schedules with special instructions, and notes specific to the railroad. The schedule is the part of a time-table which prescribes class, direction, number and movement for a regular train, usually in the form of a table with times, train numbers and other information.","TT · What is TT&TO");
C("def","Superior train","A train having precedence over another train.","SC · Definitions");
C("def","Train of superior class","A train given precedence by time-table.","SC · Definitions");
C("def","Train of superior direction","A train given precedence in the direction specified by time-table, as between opposing trains of the same class.","SC · Definitions");
C("def","Train of superior right","A train given precedence by train order.","SC · Definitions");
C("def","Section","One of two or more trains running on the same schedule, displaying signals or for which signals are displayed.","SC · Definitions");
C("def","Main track (Standard Code)","A track extending through yards and between stations, upon which trains are operated by time-table or train order, or both, or the use of which is governed by block signals.","SC · Definitions");
C("def","Siding","A track auxiliary to the main track for meeting or passing trains.","SC · Definitions");
C("def","Single track","A main track upon which trains are operated in both directions.","SC · Definitions");
C("def","Restricted speed (Standard Code)","Proceed prepared to stop short of train, obstruction, or switch not properly lined, and to look out for broken rail.","SC · Definitions");
C("def","Register station / train register","Register station: a station at which a train register is located.\nTrain register: a book or form used at designated stations for registering signals displayed, the time of arrival and departure of trains, and other information.","SC · Definitions");
C("def","Block","A length of track of defined limits, the use of which by trains and engines is governed by block signals, cab signals, or both.","SC · Definitions");
C("def","Block signal","A fixed signal at the entrance of a block to govern trains and engines entering and using that block.","SC · Definitions");
C("def","Approach signal","A fixed signal used in connection with one or more signals to govern the approach thereto.","SC · Definitions");
C("def","Automatic block system","A series of consecutive blocks governed by block signals, cab signals, or both, actuated by a train or engine, or by certain conditions affecting the use of a block.","SC · Definitions");
C("def","Fixed signal","A signal of fixed location indicating a condition affecting the movement of a train or engine.","SC · Definitions");
C("def","Interlocking","An arrangement of signals and signal appliances so interconnected that their movements must succeed each other in proper sequence, and for which interlocking rules are in effect. It may be operated manually or automatically.","SC · Definitions");
C("def","Rule 5: times shown in a schedule","Not more than two times are given for a train at any station. One time = the leaving time (unless otherwise indicated). Two times = arriving and leaving times.","SC · Rule 5");
C("def","How long was TT&TO used, and what replaced it?","About 150 years, from the mid-1800s to nearly the 1980s; it dominated from 1940 to 1960 outside signalled corridors. Radio-delivered Direct Traffic Control and track warrants replaced the agent-operators; CTC and interlockings where traffic paid for them.","TT · What is TT&TO");
C("def","GCOR: Train","One or more engines coupled, with or without cars, displaying a marker, and authorized to operate on a main track.","GC · Glossary");
C("def","GCOR: Centralized Traffic Control (CTC)","A block system that uses block signal indications to authorize train movements.","GC · Glossary");
C("def","GCOR: Direct Traffic Control (DTC) and DTC block","DTC: a DTC block or series of DTC blocks where the train dispatcher authorizes track occupancy.\nDTC block: a length of main track specified by name, identified by wayside signs reading Begin (name) Block and End (name) Block and by milepost in the timetable.","GC · Glossary");
C("def","GCOR: Control point / controlled signal","Control point: the location of absolute signals controlled by a control operator.\nControlled signal: an absolute signal controlled by a control operator.","GC · Glossary");
C("def","GCOR: Distant signal","A fixed signal outside a block system that governs the approach to a block signal, interlocking signal, or switch point indicator. It does not indicate track conditions between itself and that signal. Identified by a D.","GC · Glossary");
C("def","GCOR: Interlocking limits","The tracks between the outer opposing absolute signals of an interlocking.","GC · Glossary");
C("def","GCOR: Spring switch vs. variable switch","Spring switch: a spring returns the points to their original position after they are trailed through.\nVariable switch: marked with a V or a bowl painted yellow; when trailed through, the points stay where they were forced.","GC · Glossary");
C("def","GCOR: Current of traffic / double track","Current of traffic: the movement of trains in one direction on a main track, as specified by the rules.\nDouble track: two main tracks where the current of traffic is one way on one track and the opposite way on the other.","GC · Glossary");
C("def","GCOR: Clearance point","The location closest to a switch where it is safe for equipment, and a person riding the side of equipment, to pass equipment on an adjacent track.","GC · Glossary");
C("def","GCOR: Reverse movement","A movement opposite the authorized direction.","GC · Glossary");
C("def","GCOR: Yard (vs. yard limits)","Yard: a system of tracks, other than main tracks and sidings, used for making up trains, storing cars and other purposes.\nYard limits: a portion of MAIN track designated by yard limit signs and timetable special instructions or a track bulletin.","GC · Glossary");
C("def","GCOR: Automatic Train Control (ATC)","A system to enforce compliance with cab and wayside signal indications. If the train exceeds a predetermined speed for a given signal indication and speed is not reduced at a sufficient rate, brakes are automatically applied.","GC · Glossary");
C("def","GCOR: Automatic Train Stop System (ATS)","A system activated by wayside inductors positioned to apply the brakes automatically until the train stops.","GC · Glossary");
C("def","GCOR: Block","A length of track:\n• Between consecutive block signals\n• Between a block signal and the end of block system limits\n• In ATC limits the use of which is governed by cab signals and/or block signals","GC · Glossary");
C("def","GCOR: Block Register Territory (BRT)","A method of operation in non-signaled territory where trains, men, and equipment are authorized to occupy the main track in limits designated by the timetable.","GC · Glossary");
C("def","GCOR: Block system","A block or series of consecutive blocks within ABS, ACS, CTC, or interlocking limits.","GC · Glossary");
C("def","GCOR: Cab signal","A signal in the engineer's compartment or cab that indicates a condition affecting train movement. Cab signals are used with interlocking or block signals or without block signals.","GC · Glossary");
C("def","GCOR: Conductor / foreman","Conductor: crew member in charge of train or yard crew.\nForeman: employee in charge of work.","GC · Glossary");
C("def","GCOR: Control operator","Employee assigned to operate a CTC or interlocking control machine or authorized to grant track permits.","GC · Glossary");
C("def","GCOR: Controlled siding","A siding within CTC or interlocking limits where a signal indication authorizes the siding's use.","GC · Glossary");
C("def","GCOR: Crew member","Conductors, assistant conductors, brakemen, engineers, remote control operators, yard engine foremen, switchmen, and yard helpers.","GC · Glossary");
C("def","GCOR: Crossings at grade","Crossings that intersect at the same level.","GC · Glossary");
C("def","GCOR: Crossover","A track connection between two adjacent tracks, consisting of two switches, which is intended to be used primarily for the purpose of crossing over from one track to the other.","GC · Glossary");
C("def","GCOR: Dual control switch","A power-operated switch, moveable point frog, or derail that can also be operated by hand.","GC · Glossary");
C("def","GCOR: Electric switch lock","An electrically controlled lock that restricts the use of a hand-operated switch or derail.","GC · Glossary");
C("def","GCOR: Engine","A unit propelled by any form of energy or more than one of these units operated from a single control. Engines are used in train or yard service. Rules that apply to engines also apply to cab control cars.","GC · Glossary");
C("def","GCOR: Engineer","Also includes student engineers, firemen, hostlers, and remote control operators.","GC · Glossary");
C("def","GCOR: Equipment fouling a track","The end of rolling equipment or on-track maintenance of way equipment left between the clearance point and the switch points leading to the track on which the equipment is standing.","GC · Glossary");
C("def","GCOR: Flagman","Any employee providing flag protection as outlined in Rule 6.19 (Flag Protection) and for other purposes as outlined in the rules.","GC · Glossary");
C("def","GCOR: Interlocking signals","The fixed signals of an interlocking that govern trains using interlocking limits.","GC · Glossary");
C("def","GCOR: Main track","A track extending through yards and between stations that must not be occupied without authority or protection.","GC · Glossary");
C("def","GCOR: Men or equipment","A term referring to Engineering Department employees and their related equipment.","GC · Glossary");
C("def","GCOR: Multiple main tracks","Two or more main tracks that are used according to the timetable.","GC · Glossary");
C("def","GCOR: Pilot","An employee assigned to a train to assist an engineer or conductor who is unfamiliar with the rules or the portion of railroad the train will operate on.","GC · Glossary");
C("def","GCOR: Positive Train Control (PTC)","A safety overlay system designed to monitor train movement and prevent train to train collisions, over speed violations, movement into established work zone limits without permission, and movement over an improperly lined main track switch.","GC · Glossary");
C("def","GCOR: PTC equipped / restricted mode","PTC equipped: a locomotive equipped with an operable PTC system.\nRestricted mode: a mode where the only function provided by PTC is enforcement of the maximum speed indicated on the PTC display.","GC · Glossary");
C("def","GCOR: Proceed indication","Any block signal indication that allows a train to proceed without stopping.","GC · Glossary");
C("def","GCOR: Radio blocking","A method to establish an absolute block for a following train in non-signaled territory by direct communication with a preceding train.","GC · Glossary");
C("def","GCOR: Remote control operator (RCO) / remote control zone (RCZ)","RCO: an employee who may operate an engine with or without cars by means of a remote control transmitter.\nRemote control transmitter: a device that gives the remote control operator control of a remote control engine.\nRCZ: a portion of track(s) within definite limits designated in the timetable special instructions.","GC · Glossary");
C("def","GCOR: Restricted limits","A portion of main track designated by restricted limits signs and timetable special instructions or a track bulletin.","GC · Glossary");
C("def","GCOR: Siding","A track connected to the main track and used for meeting or passing trains. Location of sidings are shown in the timetable.","GC · Glossary");
C("def","GCOR: Signal aspect / signal indication","Signal aspect: the appearance of a fixed or cab signal.\nSignal indication: the action required by the signal aspect.","GC · Glossary");
C("def","GCOR: Station","A place designated by name in the timetable station column.","GC · Glossary");
C("def","GCOR: Switch point indicator","A light type indicator used during movement over certain switches to show that switch points fit properly.","GC · Glossary");
C("def","GCOR: Timetable / special instructions","Timetable: a publication with instructions on train, engine, or equipment movement. It also contains other essential information.\nSpecial instructions: instructions contained in the timetable or other publication.","GC · Glossary");
C("def","GCOR: Track bulletin","A notice of conditions affecting train movement. It may also authorize movement against the current of traffic where Rule 9.14 (Movement with the Current of Traffic) is in effect.","GC · Glossary");
C("def","GCOR: Track occupancy indicator","An indicator that tells whether a length of track is occupied or not.","GC · Glossary");
C("def","GCOR: Trackside warning detector","A device that indicates conditions such as overheated journals, dragging equipment, excess dimensions, shifted loads, high water, or slides.","GC · Glossary");
C("def","GCOR: Train coordination","Working limits established by a roadway worker through the use of a train's authority on a main track or other track where specific authority is required from a control operator or train dispatcher.","GC · Glossary");
C("def","GCOR: Whistle quiet zone","A designated portion of track, that includes road crossing(s) at grade where whistle signal (7) is not regularly sounded.","GC · Glossary");
C("def","GCOR: Working limits","A segment of track within definite boundaries on which movements may be made only as permitted by the employee in charge. Boundaries may be established using mile posts, station signs, timetable locations, or clearly identifiable points.","GC · Glossary");
C("def","Main track (Yard Limits guide)","Primary track connecting stations and through stations, upon which trains move at track speed.","YL · Definitions");

// Superiority & movement
C("sup","Rule S-71 (single track): how is a train superior?","By right, class or direction. Right is conferred by train order; class and direction by time-table. Right is superior to class or direction. Direction is superior as between trains of the same class.","SC · Rule S-71");
C("sup","Rule D-71 (double track): how is a train superior?","By right or class only (no superiority by direction). Right is conferred by train order; class by time-table. Right is superior to class.","SC · Rule D-71","S- rules apply to single track, D- rules to two or more tracks.");
C("sup","Rule 72","Trains of the first class are superior to those of the second; second to third; and so on.","SC · Rule 72");
C("sup","Rule S-72","Trains in the direction specified by the time-table are superior to trains of the same class in the opposite direction.","SC · Rule S-72");
C("sup","Rule 73","Extra trains are inferior to regular trains.","SC · Rule 73");
C("sup","Rule 82: when does a late regular train lose its rights?","Schedules, unless fulfilled, stay in effect for 12 hours after their time at each station. A regular train more than 12 hours behind its arriving or leaving time at any station loses both right and schedule, and can then proceed only as authorized by train order.","SC · Rule 82");
C("sup","Rule S-83","A train must not leave its initial station on any division or subdivision, or a junction, or pass from two or more tracks to single track, until it has been ascertained whether all superior trains due have arrived or left. (Register stations are designated by time-table.)","SC · Rule S-83");
C("sup","Rule 84","A train must not start until a proper signal is given.","SC · Rule 84");
C("sup","Rule 85: passing in the same direction","Trains of one schedule may pass trains of another schedule of the same class; extra trains may pass and run ahead of ____ class trains (the class is left blank in the Code) and extra trains. A section must not pass another section of the same schedule without first exchanging train orders, signals and numbers with it, and the change must be reported from the next available point of communication.","SC · Rule 85");
C("sup","Rule 86: inferior train ahead of a superior train (same direction)","Unless otherwise provided, the inferior train must be clear at the time the superior train is due to LEAVE the next station in the rear where time is shown.","SC · Rule 86");
C("sup","Rule S-87: inferior train vs. opposing superior train","The inferior train must keep out of the way. If it fails to clear the main track by the time required, it must be protected under Rule 99. Extras must clear the time of opposing regular trains by not less than 5 minutes (unless otherwise provided) and are governed by train orders with respect to opposing extras.","SC · Rule S-87","The TT&TO primer quotes 10 minutes here. The Standard Code text says 5.");
C("sup","Rule S-88: two extras meet. Who takes the siding?","The train in the inferior time-table direction, unless otherwise provided.","SC · Rule S-88");
C("sup","Rule S-89: at meeting points","The inferior train takes the siding and clears the superior train's time by not less than 5 minutes. Exception: at schedule meeting points between trains of the same class, it must clear the main track before the superior train's leaving time. The superior train must stop at schedule meeting points with same-class trains unless the switch is properly lined and the track clear. The inferior train must pull into the siding when practicable. If the inferior train must back in, it is protected per Rule 99.","SC · Rule S-89","The TT&TO primer quotes 10 minutes. The Standard Code text says 5.");
C("sup","Rule 92","A train must not leave a station in advance of its schedule leaving time.","SC · Rule 92");
C("sup","Rule 94: overtaking a disabled train","Pass it if practicable. If necessary, assume the disabled train's schedule and take its train orders, proceed to the next available point of communication and report. The disabled train assumes the right, schedule and train orders of the last train it exchanged with, and reports from the next point of communication when able.","SC · Rule 94");
C("sup","Rule 99: train MOVING where it may be overtaken","The flagman must drop lighted fusees at proper intervals and take other action needed for full protection.","SC · Rule 99");
C("sup","Rule 99: train STOPPED where it may be overtaken","The flagman goes back immediately with flagman's signals a sufficient distance to insure full protection, placing two torpedoes and, when necessary, lighted fusees. When recalled, he may return, leaving the torpedoes and a lighted fusee.","SC · Rule 99");
C("sup","Rule 99: who calls for and recalls the flagman? Who protects the front?","The engineman signals the flagman to protect the rear immediately when stopped, and recalls him when ready to proceed. The front is protected the same way when necessary. Conductors and enginemen are responsible for the protection of their trains.","SC · Rule 99");
C("sup","Rule 104: switches","Conductors are responsible for the position of switches used by them and their crews, except where switch tenders are stationed. Switches must be properly lined after use. A switch must not be left open for another train unless a member of that train's crew is in charge of it.","SC · Rule 104");
C("sup","Rule 20: signals for following sections","All sections except the last display two green flags, and by night also two green lights, in the places provided on the front of the engine.","SC · Rule 20");
C("sup","Rule 251: block signals and superiority","On designated tracks, trains run with reference to other trains in the same direction by block signals, whose indications supersede the superiority of trains.","SC · Rule 251");
C("sup","Before departure, a TT&TO crew must know four things. What are they?","1. Your own schedule (if a regular train).\n2. The schedules of superior trains due, opposing or overtaking.\n3. Whether those superior trains have arrived or left.\n4. Whether you can make the next meeting point before a superior train is due.","TT · Appendix");

// Train orders
C("to","Rule 203: numbering train orders","Numbered consecutively each day, beginning at midnight.","SC · Rule 203");
C("to","Rule 206: how trains are named in train orders","Regular trains by number: “No. 10”. Sections: “Second 10” (engine numbers may be added). Extras by engine number and direction: “Extra 798 East”. Work extras: “Work Extra 798”. A foreign road's engine: its initials precede the engine number.","SC · Rule 206");
C("to","Rule 206: stations and numerals in an order","Pronounced plainly, then spelled letter by letter: “Aurora, A-U-R-O-R-A” and “One Naught Five, O-N-E N-A-U-G-H-T F-I-V-E”.","SC · Rule 206");
C("to","Rule 207: transmitting signal","“31” or “19” followed by the direction, given to each office addressed, stating the number of copies: “31, West, copy 5” or “19, East, copy 2”.","SC · Rule 207");
C("to","Rule 211: Clearance Form A","The operator fills it out before clearing a train, without erasure or alteration: the total number of train orders and the number of each. He repeats it to the dispatcher, who records it and gives “OK”, the time and his initials, which the operator writes on the form.","SC · Rule 211");
C("to","Clearance Form A: the wire fails before the OK","If all orders for the train are complete, the operator may deliver them with Clearance Form A marked “Wire has failed”. It is acted on as though OK had been given. When the wire is restored, the operator reports each train cleared, the time and the order numbers.","SC · Rule 211");
C("to","Who must check Clearance Form A against the orders?","Conductors, enginemen and firemen must (trainmen when practicable) see that the information on Clearance Form A matches the train orders received. It is delivered with all the orders to each person addressed; the operator keeps a copy.","SC · Rule 211");
C("to","Rule 220: how long is a train order in effect?","Until fulfilled, superseded or annulled. Any part of an order specifying a particular movement may be either superseded or annulled.","SC · Rule 220");
C("to","Rule 221: the train order signal","A fixed signal at each train order office shows “stop” when an operator is on duty, changed to “proceed” only to let a train pass when there are no orders for any train in that direction. While it shows stop, trains must not leave without a Clearance Form A.","SC · Rule 221");
C("to","Rule 222: operator reports","Operators promptly record and report the time of arrival and departure of all trains and the direction of extra trains.","SC · Rule 222");
C("to","Form S-A: “No 1 meet No 2 at B”","Fixes a meeting point for opposing trains. Neither train may proceed past B until both have arrived. Normally the superior train holds the main and the inferior takes the siding. Form (2) fixes several meets in one order: “No 1 meet No 2 at B Second 4 at C and Extra 95 east at D”. Trains receiving these orders run with respect to each other to the designated points and there meet in the manner prescribed by the rules.","SC · Form S-A / TT · Forms");
C("to","Form S-C: “No 1 has right over No 2 G to X”","Gives the first-named train right over the second between the points. If the second-named train reaches X (the point last named) before No 1 arrives, it may proceed, keeping clear of No 1's schedule as required by rule. If they meet at either named point, the first-named train takes the siding unless the order says otherwise.","SC · Form S-C");
C("to","Form S-C: “Extra 37 east has right over No 3 F to A”","The regular train (No 3) must not go beyond A (the point last named) until Extra 37 east has arrived, unless authorized by train order.","SC · Form S-C (2)");
C("to","Form S-C with wait times: “Extra 72 south has right over Extra 91 north A to Z and wait at N until 2 10 p m…”","The first-named extra must not pass the waiting points before the times given unless the second-named extra has arrived. The second-named extra must clear those times at the designated points or any intermediate station by not less than five minutes.","SC · Form S-C (3)");
C("to","Form D: “No 1 has right over No 3 A to Z” (same direction)","The second-named train must clear the first-named train's time between the points as required by rule. If train order time is given (“Extra 62 east has right over No 4 Z to A and wait at Z until 12 50 p m…”), the first-named train must not pass the designated stations before the time shown, and the second-named train must clear such times as required by rule. If no time is given, the second-named train must not leave the first-named point ahead of the first-named train.","SC · Form D");
C("to","Form E: “No 1 run 50 mins late A to G”","Makes No 1's schedule between A and G 50 minutes later. Any train receiving the order runs with respect to the later time exactly as it would to the regular schedule.","SC · Form E");
C("to","Form F: sections","(1) “Eng 20 display signals and run as First 1 A to Z” is used when the number of the engine for which signals are displayed is unknown, and is followed by (2) “Eng 25 run as Second 1 A to Z”. Other forms: “Second 1 display signals B to E for Eng 99”; “Engs 20 25 and 99 run as First Second and Third 1 A to Z”.","SC · Form F");
C("to","Form G: “Eng 99 extra A to F and return to C”","Creates an extra. The extra must go all the way to F before returning to C. Variants: “Eng 99 run extra A to F”, “Eng 99 passenger extra A to F”.","SC · Form G");
C("to","Form S-H: “Eng 292 works extra 6 45 am until 5 45 pm between D and E”","Within the working limits the work extra must, standing or moving, protect itself against extra trains in both directions. The time of regular trains must be cleared.","SC · Form S-H","The TT&TO primer says it must clear the main when on the time of first class trains with the specified safety margin. The Standard Code text says regular trains.");
C("to","Form S-H modifiers","“Not protecting against eastward extra trains”: protects only against westward extras.\n“Not protecting against extra trains”: no protection against extras needed.\nIn every case the time of regular trains must still be cleared.","SC · Form S-H");
C("to","Form D-H: work extra on a named track","The work extra protects itself within the limits against extras moving with the current of traffic on the named track(s); regular trains' time must be cleared. Adding “Extra 173 east wait at E until 9 15 am…” means it protects against those trains only after the times given.","SC · Form D-H");
C("to","Form L: annulling an order","“Order No 10 is annulled.” If the order was not yet delivered, the annulment is addressed to the operator, who destroys all copies but his own and writes “Annulled by Order No __” on it. An annulled order must not be reissued under its original number.","SC · Form L");
C("to","Form S-P / P: superseding an order","Add “instead of”: “No 1 meet No 2 at C instead of B”. A superseded order is not reissued under its original number. A take-siding instruction applies only at the point in that order, not to the superseding order unless it says so.","SC · Forms S-P, P");
C("to","TT&TO primer: besides “No. 1 run 50 mins late A to G”, what other type of time order is there?","One that requires trains named to wait at certain points until a certain time.","TT · Forms","Standard Code Form E (2): “No 1 and No 3 wait at N until 9 59 a m”.");

// Signals & whistles
C("sig","Hand signal 12(a): STOP","Swung at right angle to the track.","SC · Rule 12a");
C("sig","Hand signal 12(b): REDUCED SPEED","Held horizontally at arm's length.","SC · Rule 12b");
C("sig","Hand signal 12(c): PROCEED","Raised and lowered vertically.","SC · Rule 12c");
C("sig","Hand signal 12(d): BACK","Swung vertically in a circle at right angle to the track.","SC · Rule 12d");
C("sig","Standard Code whistle: o (one short)","Apply brakes. Stop.","SC · Rule 14(a)");
C("sig","Standard Code whistle: — — (two long)","Release brakes. Proceed.","SC · Rule 14(b)");
C("sig","Standard Code whistle: — o o o","Flagman protect rear of train.","SC · Rule 14(c)");
C("sig","Standard Code whistle: o o o","When standing: back. Answer to hand signal 12(d) and communicating signal 16(c). When running: answer to communicating signal 16(d).","SC · Rule 14(h)");
C("sig","Whistle: — — o —","Approaching public crossings at grade. Prolonged or repeated until the crossing is reached (Standard Code) / until the engine completely occupies the crossing (GCOR).","SC · Rule 14(l) / GC · 5.8.2(7)");
C("sig","GCOR whistle (1): succession of short sounds","Persons or livestock on the track (other than at crossings), or warning employees of an emergency such as a derailment. Crews on other trains who hear it must stop until it is safe to proceed.","GC · 5.8.2");
C("sig","GCOR whistles (2) through (6)","(2) — : when stopped, air brakes applied, pressure equalized\n(3) — — : release brakes, proceed\n(4) o o : acknowledgment of any signal not otherwise provided for\n(5) o o o : when stopped, back up\n(6) o o o o : request for a signal to be given or repeated","GC · 5.8.2");
C("sig","GCOR whistle (8): — o","Approaching men or equipment on or near the track, regardless of whistle prohibitions. Then sound (4) intermittently until the head end has passed them.","GC · 5.8.2");
C("sig","GCOR crossing whistle timing","Over 45 MPH: start at or about the crossing sign, but not more than 1/4 mile before the crossing.\n45 MPH or less: start at least 15 but not more than 20 seconds before entering the crossing.\nNo crossing sign: start at least 15 but not more than 20 seconds before entering the crossing, but not more than 1/4 mile before the crossing.\nMovement starts less than 1/4 mile from a crossing: the signal may be sounded less than 15 seconds before the crossing when it is clearly seen traffic is not approaching or stopped at the crossing, or when crossing gates are fully lowered.","GC · 5.8.2(7)");
C("sig","Which GCOR whistle signals can't be replaced by radio or other communication?","(1) succession of shorts, (7) crossing, and (8) approaching men or equipment.","GC · 5.8.2");
C("sig","GCOR: when must the bell be rung?","Before moving (except momentary stop-and-start switching), as a warning when necessary, approaching men or equipment, and approaching public crossings (start at the sign and ring until the crossing is occupied).","GC · 5.8.1");
C("sig","GCOR: whistle fails","If no other unit can lead, continue with the bell ringing continuously and stop before each public crossing so a crew member can warn traffic, unless the gates are fully down or no traffic is approaching or stopped.","GC · 5.8.3");
C("sig","Aspect vs. indication vs. name","Aspect: what the signal looks like (color, light positions, blade position).\nIndication: what it tells you (stop, approach, clear…).\nName: the railroad's name for the indication, usually by rule number (e.g. NYC Rule 281-B Approach Limited).","SG · Definitions");
C("sig","Route signaling vs. speed signaling","Route: the signal tells you which route and the state of blocks ahead; diverging speeds come from the timetable. Western US before UCOR, and most model railroads.\nSpeed: the signal tells you how fast to go past it. Eastern US, and western roads after UCOR.","SG · Definitions");
C("sig","ABS vs. APB","ABS (Automatic Block Signals): track divided into electrically isolated blocks, each with a signal at its entrance, interconnected; automatic.\nAPB (Absolute Permissive Block): when a train passes a head block at a siding, all opposing signals go to stop through to the head block at the next siding. Also automatic.","SG · Definitions");
C("sig","CTC and interlocking (signals guide)","CTC: a dispatcher, possibly far away, controls turnouts and signals at control points (CPs or OS sections), usually at siding ends.\nInterlocking: turnouts and signals set up to prevent conflicting movements through the limits, electrically or mechanically, usually from a tower.","SG · Definitions");
C("sig","Route signal indications (basic chart)","Clear (green): next two blocks are unoccupied.\nApproach (yellow): next block is unoccupied.\nDiverging Clear (red over green): next two blocks are unoccupied on diverging route.\nDiverging Approach (red over yellow): next block is unoccupied on diverging route.\nStop: red, or red over red.","SG · Signal chart");
C("sig","“It's not red unless it's ALL red.”","A two-head signal with red over green or red over yellow is a diverging indication, not a stop. Only all-red is stop. At stop, what you may do depends on the plate on the mast.","SG · Route indications");
C("sig","Signal plates: A, none, number","A plate: absolute; at stop, may not pass until permission from whoever controls it (usually the CTC dispatcher).\nNo plate: same as an A plate.\nNumber plate (usually nearest milepost): after stopping, proceed at restricted speed. Some railroads allow a train to proceed at restricted speed without stopping if they are to immediately enter a siding.","SG · Signal signage");
C("sig","Signal plates: SA, D, G, P","SA: semi-automatic, an interlocking signal with an ABS part; at stop, get permission from the operator.\nD: distant signal, warns of an interlocking ahead in dark territory.\nG: grade signal (with number plate); may pass at restricted speed without stopping.\nP: protective; a detector (high water, slide…) in the block that the crew must inspect. Type of detector and milepost will be in the employee timetable.","SG · Signal signage");
C("sig","How may fixed signal aspects be shown? (Standard Code)","By position of semaphore arms, color of lights, position of lights, flashing of lights, or a combination of color, position and flashing.","SC · Fixed Signals");
{
  const byR=Object.fromEntries(ASPECTS.map(a=>[a.r,a]));
  const MARK="It is designated by a letter plate, a marker light, the shape of the arm, or a combination of these.";
  ASPECTS.forEach(a=>{
    if(a.w.length!==3||a.w.some(r=>!byR[r]||r===a.r))throw new Error("ASPECTS: rule "+a.r+" needs three other rules as wrong choices");
    const marked=a.mark?" (with the marking that designates it)":"";
    const notes=[a.mark?MARK:"",a.more?"The Code also draws this aspect with fewer or different arms.":"",a.note||""].filter(Boolean).join(" ");
    C("sig",`Speed signal${marked}, arms top to bottom: ${armWords(a.arms)}. Name and indication?`,`Rule ${a.r}, ${a.name}: ${a.ind}.`,"SC · Rule "+a.r,notes||undefined,a.arms);
    Q("sig",`What does this signal${marked} indicate? Arms top to bottom: ${armWords(a.arms)}.`,[a.ind,...a.w.map(r=>byR[r].ind)],`Rule ${a.r}, ${a.name}.${a.mark?" "+MARK:""}`,"SC · Rule "+a.r,a.arms);
  });
}
C("sig","GCOR 5.8.4: in a whistle quiet zone, when may signal (7) be sounded?","Within designated whistle quiet zones, signal (7) must not be sounded approaching public crossings at grade except when:\n• Necessary to provide warning in an emergency\n• Notified automatic warning devices are malfunctioning\n• Notified automatic warning devices are out of service\n• The whistle quiet zone is not in effect during specified hours","GC · 5.8.4");
C("sig","GCOR 5.8.2: whistle prohibitions, and employees working nearby","The whistle may be used at anytime as a warning regardless of any whistle prohibitions. When other employees are working in the immediate area, sound the required whistle signal before moving.","GC · 5.8.2");
C("sig","Typical signal placement: Automatic Block Signals","At ends of sidings, both signals are just clear of switch points.\nIntermediate block signals are normally located opposite each other.","SG · Signal placement");
C("sig","Typical signal placement: Centralized Traffic Control","Trailing point signals are at the clearance point.\nA dwarf signal is often used on the siding.\nThe facing point signal is just clear of the switch points.\nNewer installations may use field side signals.","SG · Signal placement");
C("sig","Typical signal placement: Interlocking Plants","Interlocking plants have a signal for every track where it enters the interlocking limits.\nIf a signal bridge is used, signal heads are to the right of each track.","SG · Signal placement");
Q("sig","Under the Standard Code, a Stop and proceed signal (Rule 291) is told apart from a Stop signal by…",["A letter plate, marker light, shape of arm, or a combination of these","The color of its lights only","Its height above the rail","A number painted on the arm"],"Rules 289 and 291: designate by a letter plate, a marker light, the shape of the arm, or a combination of these distinguishing features. The number of arms does not: the Code draws Stop (292) with three, two or one arms.","SC · Rules 289, 291");

// Semaphores
C("sem","Semaphore blade horizontal","Always stop (red). On a model railroad, treat it as a closed gate.","SM");
C("sem","Upper vs. lower quadrant","Upper: blade moves UP from horizontal to clear; 0°, 45°, 90°. Came about around 1900.\nLower: blade moves DOWN; 0°, 30°, 60°.","SM");
C("sem","Why is a lower-quadrant semaphore not fail-safe?","If the mechanism, power, air or cable fails, gravity drops the blade toward approach or clear, so a stop signal could show proceed.","SM");
C("sem","Major parts of a semaphore","Blade, roundels (lenses), spectacle (holds the roundels), lamp, actuating mechanism, housing.","SM");
C("sem","FRA 236.23: semaphore aspects are shown by…","Blade position, color of lights, position of lights, flashing of lights, or any combination. Indications may be qualified by a marker plate, number plate, letter plate, marker light, or the shape/color of the blade.","SM");
C("sem","Semaphores: origins and uses","Patented in the 1840s by John James Stevens; first lit by kerosene, later electric bulbs. Used as train order boards or as train movement signals; high signals or dwarfs; one, two or three positions.","SM");
C("sem","Single-position semaphores","Fixed permanently at 45° (approach) as a warning of something ahead such as a bridge; commonly used for a restricting indication.","SM");
C("sem","Semaphore lens colors","Red\nPurple (sometimes used in very early signals in lieu of red)\nYellow\nGreen\nand/or White (in very early signals before green lens was perfected)","SM · Forms");
C("sem","Semaphore blades: ends, sizes, colors","Blade ends could be Square, Round, Pointed, or Fishtail.\nBlade sizes vary.\nBlade colors vary, often relating to their meaning.","SM · Forms");
C("sem","How were semaphores operated?","By mechanical means (either pipes or cables (wires)), pneumatic, electro-pneumatic, or electrical. Powered semaphores can have the power unit/actuator at either the base or top of the mast.","SM · Forms");
C("sem","Semaphore high signals: how high?","Often with a single arm (or the lower arm of a dual or triple indicating signal) 17 feet (or more) off the ground. Semaphores also came in dwarf versions.","SM · Forms");
C("sem","Semaphore mounting and signals per mast","Mounted at ground level, or on a mast, signal bridge, cantilever bridge, or building.\nOne, two, or three semaphore signals on a single mast for a single indication, or a combination of signals on the same mast.\nSemaphores are sometimes “Smashboard” style.","SM · Forms");

// Yard limits
C("yl","What are yard limits?","A section of MAIN track, usually defined by mileposts in the timetable and marked by signs (such as a forked stick), within which movements follow the yard limit rule (Standard Code Rule 93; GCOR 6.13).","YL");
C("yl","Rule 93 (Standard Code)","Within yard limits the main track may be used, clearing the time of first-class trains at the next station where time is shown. Protection against ____ class (left blank in the Code; the TT&TO primer fills in second class), extra trains and engines is not required; they move at yard speed unless the main track is known to be clear. No move against the current of traffic until protection has been provided.","SC · Rule 93","Wording differs between guides; see Guide notes.");
C("yl","Inside yard limits, who is in charge?","The yardmaster or agent if one is on duty; otherwise generally the conductor or switch crew foreman of the first train there.","YL");
C("yl","Why have yard limits?","Many trains and engines need short stretches of main track (e.g. a yard ladder joined to the main). Crews can work together easily, and the dispatcher doesn't have to issue many fast-changing orders or warrants.","YL");
C("yl","GCOR 6.13: yard limits","Trains and engines may use the main track without protecting against other trains or engines. Engines give way to trains as they approach and must not delay passenger trains. All movements at restricted speed unless under a block signal more favorable than Approach.","GC · 6.13");
C("yl","GCOR 6.13: yard limits in CTC and against the current","In CTC territory the control operator must authorize any main track movement. Against the current of traffic: only when authorized or protected by track warrant, track bulletin, yardmaster or other authorized employee. Yard limits are in effect continuously unless special instructions or a bulletin say otherwise.","GC · 6.13");
C("yl","GCOR 6.13: a block signal that may require restricted speed due to yard limits (Diagrams B and C)","Upon observing or having advance knowledge that a block signal may require restricted speed due to yard limits, if entering or within yard limits, the movement must be at restricted speed at that block signal, or as soon as possible thereafter, consistent with good train handling.","GC · 6.13");
C("yl","GCOR 6.13: yard limits in Track Permit territory","All movements must receive permission from the control operator to enter the main track or to cross over from one main track to another as follows:\n• A controlled signal displays a proceed indication\n• A track permit is issued\n• Verbal permission is granted if no track permit is in effect (Rule 9.17 applies)","GC · 6.13");
C("yl","Yard Limits guide: at what speed are movements within yard limits made?","All movements must be at Restricted Speed (unless block signal protection is present).","YL · Definitions");

// Track warrants
C("twc","Track Warrant Control (TWC)","A system to authorize trains to move across a specified territory, and to authorize men and equipment to work on or near main track. The dispatcher gives verbal instructions; the field employee copies them on a form and repeats them back; the dispatcher gives an OK time.","TW · Defined");
C("twc","“An authority without an OK time is…”","“…just a piece of paper.” A track warrant is not in effect until the OK time is shown on it.","TW · Defined / GC · 14.9");
C("twc","GCOR 14.9: steps to copy a track warrant","1. Employee writes all the information.\n2. Employee repeats it (preprinted and written words) to the dispatcher.\n3. Dispatcher checks it and says “OK”, the time and initials.\n4. Employee writes the OK time and initials and repeats them.","GC · 14.9");
C("twc","Who must have a copy of the track warrant?","The conductor and the engineer each, and every crew member must read and understand it. The copy must show the date.","GC · 14.9");
C("twc","First named point","When a station name is the first named point, authority extends from and includes the LAST siding switch there (from the station sign if no siding).","GC · 14.2 / TW");
C("twc","Last named point","When a station name is the last named point, authority extends to and includes the FIRST siding switch there (to the station sign if no siding). Memory aid: first is last and last is first.","GC · 14.2 / TW");
C("twc","“Hold main track at last named point” (Box 8)","Authority extends to but does NOT include the last siding switch at the last named point.","GC · 14.2");
C("twc","GCOR 14.3: switch at either end of the limits","The train must not foul a switch at either end of its limits where an opposing train may use that switch to clear the main track.","GC · 14.3");
C("twc","Box 2 vs. Box 4","Box 2 (Proceed from __ to __): one direction only; backing up needs permission for a reverse move.\nBox 4 (Work between __ and __): movement in both directions, for work trains and locals.","TW · Authority");
C("twc","Track warrant boxes 1–6","1 Track warrant no. __ is void\n2 Proceed from __ to __ on __ track\n3 Proceed from __ to __ on __ track\n4 Work between __ and __ on __ track\n5 Not in effect until __\n6 This authority expires at __","GC · 14.0 form");
C("twc","Track warrant boxes 7–11","7 Not in effect until after arrival of __ at __\n8 Hold main track at last named point\n9 Do not foul limits ahead of __\n10 Clear main track at last named point\n11 Between __ and __ make all movements at restricted speed. Limits occupied by train.","GC · 14.0 form","Worked example, warrant 705 to Eng 1547: Box 9 “do not foul limits ahead of 4449E” reinforces that Eng 1547 must be out of the way. Box 11 “between Kara and ES Lori make all movements at restricted speed” is an affirmative reminder to go slow because two trains will be on the main there.");
C("twc","Track warrant boxes 12–17","12 Restricted speed, limits occupied by men or equipment\n13, 14 Do not exceed __ MPH between __ and __\n15 Flag protection not required against following trains on the same track\n16 Track bulletins in effect\n17 Other specific instructions (e.g. “joint with 1547 between ES Lori and Kara”)","GC · 14.0 form");
C("twc","Which boxes does the TWC guide say model railroads can drop?","Box 12 (men and equipment), Boxes 5 and 6 (times), Boxes 13 and 14 (speed restrictions) and Box 15 (dispatcher protecting the rear).","TW · Selected rules");
C("twc","How long does a track warrant stay in effect?","Until the field employee releases it. Report clear of the limits as soon as practicable.","TW · Selected rules");
C("twc","What does “clear of the limits” require?","The whole train (not just the engine) clear of the warrant limits and off the main track, with switches restored to normal position (except within yard limits).","TW · Selected rules");
C("twc","Does a track warrant govern sidings?","No. Track warrants govern only the main track. In sidings and other tracks, move at a speed that lets you stop within half the range of vision short of any obstruction or improperly lined switch.","TW · Selected rules");
C("twc","Who may occupy the main track in TWC without a warrant?","No one, except within yard limits (or restricted limits). Track warrant instructions must be followed where yard limits or restricted limits are in effect.","TW · Selected rules / GC · 14.1");
C("twc","Reading a track warrant to the dispatcher","Read all the words on the form, not just the box numbers and blanks. Tell the dispatcher when ready to copy.","TW · Selected rules");
C("twc","GCOR 14.8: requesting a warrant","Tell the dispatcher what movements will be made and, when necessary, which tracks and how much time is required.","GC · 14.8");
C("twc","GCOR 14.7: clearing by a hand-operated switch","Outside yard or restricted limits, tell the dispatcher the switch position and that it is locked when reporting clear. The dispatcher repeats it and the employee confirms it.","GC · 14.7");
C("twc","GCOR 14.7: no crew on the rear. How do you know the train is complete?","A rear-end telemetry device, with air pressure on the head-end device showing brake pipe continuity; an employee verifies the marker; a crew member sees the rear car with the marker; an inspection while stopped; or matching axle counts from two trackside detectors.","GC · 14.7");
C("twc","Example: 844 West gets “Not in effect until after arrival of 2211 East at Olga Yard”","Box 7. Warrant 702 does not become usable until 2211 East arrives at Olga Yard; then 2211's warrant 701 is reported clear and voided.","TW · Worked example");
C("twc","GCOR 14.9: a track warrant that restricts movement or previously granted authority","It cannot be considered in effect by the train dispatcher until acknowledgment of the “OK” has been received. Employees may relay track warrants.","GC · 14.9");
C("twc","GCOR 14.9.1: duplicated track warrants","Employees who reproduce track warrants with a duplicating machine do not need to repeat them to the train dispatcher. Duplicated track warrants must not be delivered or used until they are checked and verified as:\n• Legible\n• Duplicated in their entirety","GC · 14.9.1");
C("twc","TWC guide: what OK must be received before a track warrant may be acted upon?","The OK could be OK time and initials, or just initials, or simply OK.","TW · Selected rules");
C("twc","TWC guide: how is the dispatcher's record of train movements marked?","Use a pencil so you can erase authority when released. Draw a line for each authority issued.\nStraight line with arrow up or down: “hold main track”.\nStraight line with arrow pointing left or right: “clear main track”.","TW · Dispatcher record");

// GCOR crew & speed
C("gcor","GCOR 6.27: restricted speed","A speed that allows stopping within half the range of vision short of a train, engine, car, men or equipment fouling the track, stop signal, or derail or switch lined improperly. Look out for broken rail and do not exceed 20 MPH, until the leading wheels pass the point where restricted speed ends.","GC · 6.27");
C("gcor","GCOR 6.28: movement on other than main track","Except on a main track or where a block system is in effect, move at a speed that allows stopping within half the range of vision short of the same list of obstructions as restricted speed.","GC · 6.28");
C("gcor","GCOR 6.25: movement against the current of traffic","Must be authorized by track bulletin or track warrant, except under yard limits, restricted limits, track permits, signal protection by lining a switch in ABS, or DTC. Approach block and interlocking signals prepared to stop unless they indicate proceed.","GC · 6.25");
C("gcor","GCOR 1.47A: the conductor","Supervises the operation and administration of the train; everyone on it obeys the conductor's instructions unless they endanger the train's safety or violate the rules. If trains combine, the senior conductor takes charge. In doubt about authority or safety, consult the engineer, who is equally responsible. Certified conductors must have a current certificate in their possession while on duty.\nMust advise the engineer and train dispatcher of any restriction placed on equipment being handled.\nFreight conductors are responsible for the freight carried by their train and for ensuring it is delivered with any accompanying documents to its destination or terminals; they must maintain any required records.","GC · 1.47A");
C("gcor","GCOR 1.47A: conductor reminders","The conductor reminds the engineer when approaching limits of authority, a track warrant, track bulletin or radio speed restriction: after passing the last station, but at least 2 miles from the restriction.","GC · 1.47A");
C("gcor","GCOR 1.47B: the engineer","Responsible for safely and efficiently operating the engine; crew obey the engineer's instructions about operating it. A student engineer or other qualified employee may operate the engine under close supervision of the engineer. Any employee that operates an engine must have a current certificate in their possession. Must check with the conductor whether any cars or units need special handling. When no conductor is present, crew obey the engineer on rules, safety and protection.","GC · 1.47B");
C("gcor","GCOR 1.47C: crew members in the engine compartment","Crew in the engine control compartment communicate to each other any restrictions or other known conditions affecting safe operation sufficiently in advance to allow the engineer to take proper action, and remind the engineer if proper action is not being taken. They call out the name of each signal as soon as it is visible or audible and keep watching, announcing any change of aspect, until passing it. If they disagree on the indication, treat it as the most restrictive one observed.\nWhen the engineer and/or conductor fail to comply with a signal indication, restriction or rule, crew members must immediately take action to ensure safety, using the emergency brake valve to stop the train, if necessary.","GC · 1.47C");
C("gcor","GCOR 1.46: yardmaster","Directly supervises yard crews, clerks and others in the yard; responsible for prompt movement of cars and proper make-up of trains. Where a yardmaster is on duty, train, engine and yard crews follow the yardmaster's instructions.","GC · 1.46");
C("gcor","GCOR 1.44 / 1.45: dispatcher and operators","Dispatchers supervise train movement and the employees connected with it. Control operators and operators work under the dispatcher's direction for track warrants, bulletins, lineups and train movements.","GC · 1.44, 1.45");
C("gcor","GCOR 1.43: engine stopped in a tunnel and can't move promptly","Shut down the diesel at once (and Waukesha or similar engines), make a full service air brake application, apply hand brakes. Passenger trains (also when stopped in deep snow) shut off air circulating systems, shut air intake shutters and turn off blower fans. The dispatcher should be notified immediately. These requirements do not apply if air currents carry the exhaust gases away from the train; safety of passengers and crew members must be the first consideration.","GC · 1.43");
C("gcor","Unattended burning fusee","Stop, then proceed at restricted speed for 1 mile beyond the fusee. A fusee beyond the first rail of an adjacent track does not apply to your track.","GC · 5.6");
C("gcor","GCOR 6.26: multiple main tracks","Multiple main tracks will be designated by name or number. When necessary, track use will be indicated in the special instructions.","GC · 6.26");

/* ---------- PRACTICE QUESTIONS (correct answer listed first; shuffled on screen) ---------- */
Q("def","Under the Standard Code, what is a regular train?",["A train authorized by time-table schedule","A train authorized by train order","Any first-class train","Any train displaying white flags"],"Regular train: authorized by time-table schedule. An extra is not.","SC · Definitions");
Q("def","Which is NOT one of the three designations of an extra train in the Standard Code?",["Freight Extra","Passenger Extra","Work Extra","Extra"],"The three are Extra, Passenger Extra and Work Extra.","SC · Definitions");
Q("def","The part of a time-table that prescribes class, direction, number and movement for a regular train is the…",["Schedule","Train register","Special instructions","Clearance"],"That is the Standard Code definition of a schedule.","SC · Definitions");
Q("def","A train given precedence by train order is a train of superior…",["Right","Class","Direction","Schedule"],"Right is conferred by train order; class and direction by time-table.","SC · Definitions");
Q("def","A train given precedence by time-table over opposing trains of the same class is a train of superior…",["Direction","Right","Class","Section"],"Superior direction applies between opposing trains of the same class.","SC · Definitions");
Q("def","What is a section?",["One of two or more trains running on the same schedule","A length of track between two signals","Part of a time-table for one subdivision","A train running extra over part of a division"],"A section is one of two or more trains on the same schedule, displaying signals or for which signals are displayed.","SC · Definitions");
Q("def","The Standard Code definition of restricted speed is…",["Proceed prepared to stop short of train, obstruction, or switch not properly lined, and look out for broken rail","Not exceeding 20 MPH","Half of maximum authorized speed","Not exceeding 15 MPH and prepared to stop at the next signal"],"The 20 MPH limit is GCOR 6.27. The Standard Code definition gives no figure.","SC · Definitions");
Q("def","A schedule shows only one time for a train at a station. Unless otherwise indicated, that time is the…",["Leaving time","Arriving time","Meeting time","Time the train must be in the clear"],"Rule 5: one time is the leaving time; two times are arriving and leaving.","SC · Rule 5");
Q("def","Under the Standard Code, a single track is…",["A main track upon which trains are operated in both directions","A main track with only one siding","Any track not in a block system","A track used by trains in one direction only"],"Single track: a main track on which trains run in both directions.","SC · Definitions");
Q("def","In the GCOR, a distant signal is identified by…",["A D","An A","A G","A P"],"A distant signal governs the approach to a block or interlocking signal and is identified by a D.","GC · Glossary");
Q("def","A switch marked with a V or a yellow-painted bowl that stays where it was forced when trailed through is a…",["Variable switch","Spring switch","Dual control switch","Electric lock switch"],"Variable switch. A spring switch returns to its original position.","GC · Glossary");
Q("def","GCOR interlocking limits are the tracks between…",["The outer opposing absolute signals of an interlocking","The first and last switches of the interlocking","The tower and the distant signal","Two consecutive control points"],"Interlocking limits: between outer opposing absolute signals.","GC · Glossary");
Q("def","GCOR: yard limits are a portion of…",["Main track","Yard track","Siding","Any track in a terminal"],"Yard limits are a portion of main track designated by signs and timetable or bulletin. A yard is the non-main tracks.","GC · Glossary");
Q("def","GCOR: a length of track between a block signal and the end of block system limits is a…",["Block","Block system","Control point","Interlocking limits"],"A block is also the length between consecutive block signals, or in ATC limits governed by cab and/or block signals.","GC · Glossary");
Q("def","In the GCOR, a proceed indication is…",["Any block signal indication that allows a train to proceed without stopping","Only a Clear indication","Any indication that allows a train to proceed after stopping","Verbal permission from the control operator"],"GCOR glossary.","GC · Glossary");
Q("def","GCOR: restricted limits are a portion of…",["Main track designated by restricted limits signs and timetable special instructions or a track bulletin","Yard track designated by restricted limits signs","Siding designated in the timetable","Track within interlocking limits"],"Restricted limits, like yard limits, are main track.","GC · Glossary");
Q("def","In the GCOR, a track bulletin is…",["A notice of conditions affecting train movement","A publication with instructions on train, engine, or equipment movement","Instructions contained in the timetable or other publication","An indicator that tells whether a length of track is occupied"],"A track bulletin may also authorize movement against the current of traffic where Rule 9.14 is in effect. The other answers are the timetable, special instructions and a track occupancy indicator.","GC · Glossary");
Q("def","A siding within CTC or interlocking limits where a signal indication authorizes its use is a…",["Controlled siding","Control point","Crossover","Multiple main track"],"GCOR glossary.","GC · Glossary");
Q("def","GCOR: a crossover is a track connection between two adjacent tracks consisting of…",["Two switches","One switch","One switch and a derail","A crossing at grade"],"Intended primarily for crossing over from one track to the other.","GC · Glossary");
Q("def","A power-operated switch, moveable point frog, or derail that can also be operated by hand is a…",["Dual control switch","Electric switch lock","Spring switch","Variable switch"],"An electric switch lock restricts the use of a hand-operated switch or derail.","GC · Glossary");
Q("def","Within working limits, movements may be made only…",["As permitted by the employee in charge","As permitted by the train dispatcher","At restricted speed, without permission","As permitted by the yardmaster"],"Boundaries may be set by mile posts, station signs, timetable locations, or clearly identifiable points.","GC · Glossary");
Q("def","In the GCOR, “men or equipment” refers to…",["Engineering Department employees and their related equipment","Train and engine crews and their engines","Rolling equipment left fouling a track","Any employee on or near the track"],"GCOR glossary.","GC · Glossary");
Q("def","GCOR: a main track extends through yards and between stations and…",["Must not be occupied without authority or protection","Is used only by trains operated by timetable","Is governed only by block signals","May be occupied by any engine at restricted speed"],"Compare the Standard Code definition, which names time-table, train order and block signals.","GC · Glossary");
Q("def","The Yard Limits guide defines main track as primary track connecting stations and through stations, upon which trains move at…",["Track speed","Restricted speed","Yard speed","Reduced speed"],"Yard Limits guide p2: yard limits are a section of main track, which is primary track upon which trains move at track speed.","YL · Definitions");

Q("sup","Under Rule S-71, which order of precedence is correct?",["Right is superior to class or direction","Class is superior to right","Direction is superior to class","Direction is superior to right"],"Right (by train order) beats class or direction; direction only decides between trains of the same class.","SC · Rule S-71");
Q("sup","Under Rule D-71 (double track), a train is superior by…",["Right or class","Right, class or direction","Class or direction","Direction only"],"On double track the D-71 rule drops superiority by direction.","SC · Rule D-71");
Q("sup","Rule 73 states that extra trains are…",["Inferior to regular trains","Superior to second-class trains","Equal to the lowest class","Superior when running in the superior direction"],"Rule 73: extra trains are inferior to regular trains.","SC · Rule 73");
Q("sup","A regular train is more than 12 hours behind its schedule at a station. It…",["Loses both right and schedule and may proceed only by train order","Becomes an extra automatically","Keeps its schedule but loses right","May proceed on its schedule at restricted speed"],"Rule 82: more than 12 hours late = loses right and schedule; train order only.","SC · Rule 82");
Q("sup","For how long are time-table schedules in effect after their time at each station, unless fulfilled?",["12 hours","8 hours","24 hours","Until the end of the time-table day"],"Rule 82: 12 hours.","SC · Rule 82");
Q("sup","Before leaving its initial station, a train must ascertain…",["Whether all superior trains due have arrived or left","That it has a clearance from every operator on the division","That the block ahead is clear","Whether all extras on the division have reported clear"],"Rule S-83. Register stations are named in the time-table.","SC · Rule S-83");
Q("sup","An inferior train is ahead of a superior train moving in the same direction. When must it be clear?",["At the time the superior train is due to leave the next station in the rear where time is shown","5 minutes before the superior train is due at the next station ahead","When the superior train is in sight","10 minutes before the superior train is due at its own location"],"Rule 86, illustrated in the primer: if No. 1 leaves Willington at 7:11 AM, the work extra ahead must be off the main by 7:11.","SC · Rule 86 / TT");
Q("sup","Under the Standard Code text, an extra must clear the time of an opposing regular train by not less than…",["5 minutes","10 minutes","3 minutes","15 minutes"],"S-87 in the Standard Code says 5 minutes. The TT&TO primer quotes 10, so check the rulebook a question refers to.","SC · Rule S-87");
Q("sup","Two extra trains meet. Unless otherwise provided, which takes the siding?",["The train in the inferior time-table direction","The train with the higher engine number","The train that arrives first","The train with the most cars"],"Rule S-88.","SC · Rule S-88");
Q("sup","At a schedule meeting point between two trains of the same class, the inferior train must…",["Clear the main track before the leaving time of the superior train","Clear the superior train's time by 5 minutes","Hold the main and wait","Flag the superior train"],"S-89's exception for same-class schedule meets: clear before the superior train's leaving time.","SC · Rule S-89");
Q("sup","The superior train at a schedule meeting point with a same-class train must stop unless…",["The switch is properly lined and the track is clear","It is more than 5 minutes late","It holds a meet order","It is a passenger train"],"S-89.","SC · Rule S-89");
Q("sup","If the inferior train must back into the siding at a meeting point, it must…",["Be protected as prescribed by Rule 99","Get a train order first","Sound — — o —","Have the superior train wait 10 minutes"],"S-89: backing in requires Rule 99 flag protection unless otherwise provided.","SC · Rule S-89");
Q("sup","A train may leave a station ahead of its schedule leaving time when…",["Never; Rule 92 prohibits it","It is a first-class train","The dispatcher verbally allows it","No opposing trains are due"],"Rule 92: a train must not leave a station in advance of its schedule leaving time.","SC · Rule 92");
Q("sup","Under Rule 99, a train stopped where it may be overtaken: the flagman goes back and places…",["Two torpedoes and, when necessary, lighted fusees","One torpedo and a red flag","Three torpedoes","A red lantern only"],"Two torpedoes; leave the torpedoes and a lighted fusee when recalled.","SC · Rule 99");
Q("sup","Under Rule 99, a MOVING train that may be overtaken is protected by…",["The flagman dropping lighted fusees at proper intervals","Placing torpedoes every quarter mile","Sounding — o o o continuously","Displaying green flags"],"Moving: drop lighted fusees. Stopped: go back with signals and place torpedoes.","SC · Rule 99");
Q("sup","Who signals the flagman to go back and protect the rear?",["The engineman","The conductor","The operator","The dispatcher"],"Rule 99: the engineman signals immediately (whistle — o o o, Rule 14(c)) and recalls the flagman when ready.","SC · Rule 99");
Q("sup","Who is responsible for the position of switches used by a crew (where there are no switch tenders)?",["The conductor","The engineman","The section foreman","The operator"],"Rule 104.","SC · Rule 104");
Q("sup","A train overtakes another so disabled that it cannot pass. If necessary, the overtaking train…",["Assumes the disabled train's schedule and takes its train orders","Must wait for a train order before passing","Couples on and pushes it to the next siding","Becomes an extra"],"Rule 94. The disabled train then assumes the schedule and orders of the last train it exchanged with.","SC · Rule 94");
Q("sup","Which sections display two green flags (two green lights at night) on the engine?",["All sections except the last","Only the first section","Only the last section","Every section"],"Rule 20: green signals tell others another section follows.","SC · Rule 20");
Q("sup","A section wants to pass another section of the same schedule. First it must…",["Exchange train orders, signals and numbers with the section to be passed","Get a train order from the dispatcher","Wait 10 minutes","Display white flags"],"Rule 85; the change must then be reported from the next point of communication.","SC · Rule 85");
Q("sup","Rule 251: where block signals govern same-direction movement on designated tracks, their indications…",["Supersede the superiority of trains","Apply only to extra trains","Must be confirmed by train order","Apply only at night"],"Rule 251.","SC · Rule 251");

Q("to","Train orders are numbered consecutively…",["Each day, beginning at midnight","Each trick, beginning at shift change","Through the year","Per train"],"Rule 203.","SC · Rule 203");
Q("to","How is Extra engine 798 running west designated in a train order?",["Extra 798 West","No. 798 West","Work Extra 798","West Extra 798"],"Rule 206: engine number and direction. “Work Extra 798” is for a work extra.","SC · Rule 206");
Q("to","How is the second section of No. 10 designated?",["Second 10","No. 10-2","No. 10 Second","Extra 10"],"Rule 206.","SC · Rule 206");
Q("to","How is the number 105 sent in the body of a train order?",["One Naught Five, O-N-E N-A-U-G-H-T F-I-V-E","One hundred five","1-0-5","One Zero Five"],"Rule 206: pronounce, then spell letter by letter; zero is “naught”.","SC · Rule 206");
Q("to","Which is the correct Rule 207 transmitting signal?",["“31, West, copy 5”","“Copy 5 West”","“Order 31 for Extra West”","“West 19 five”"],"“31” or “19”, then direction, then number of copies.","SC · Rule 207");
Q("to","Clearance Form A must show…",["The total number of train orders and the number of each order","Only the train's engine number","The names of the crew","The train's tonnage"],"Rule 211, filled out without erasure or alteration.","SC · Rule 211");
Q("to","Communication fails before Clearance Form A is OK'd, but all orders are complete. The operator…",["May deliver the orders and clearance marked “Wire has failed”","Must hold the train until the wire is restored","Must void the orders","Gives the train a verbal OK"],"Rule 211. It is acted on as though OK had been given.","SC · Rule 211");
Q("to","A train order stays in effect until it is…",["Fulfilled, superseded or annulled","The train reaches its terminal","Midnight","12 hours after issue"],"Rule 220.","SC · Rule 220");
Q("to","The fixed signal at a train order office shows stop. A train may leave only…",["With a Clearance Form A","After waiting 5 minutes","When the operator waves it by","If it has no orders"],"Rule 221.","SC · Rule 221");
Q("to","Order: “No 1 meet No 2 at B.” What does it mean?",["Neither train may go past B until both have arrived","No 1 must take the siding at B","No 2 must wait at B 10 minutes","No 1 has right over No 2 to B"],"Form S-A. Normally the superior train holds the main.","SC · Form S-A / TT");
Q("to","Order: “No 1 has right over No 2 G to X.” No 2 reaches X before No 1 arrives. No 2…",["May proceed, keeping clear of No 1's schedule as required by rule","Must wait at X for No 1","Must take the siding at X","Must get a new order"],"Form S-C (1).","SC · Form S-C");
Q("to","Under a Form S-C right-over order, the two trains meet at one of the named points. Unless the order says otherwise, who takes the siding?",["The first-named train","The second-named train","The inferior train by class","The train that arrives last"],"Form S-C: the first-named train takes the siding at either designated point.","SC · Form S-C");
Q("to","“Extra 37 east has right over No 3 F to A.” No 3 must not go beyond…",["A, until Extra 37 east has arrived","F, until Extra 37 east has left","Any station without a new order","A, until 5 minutes after Extra 37's time"],"Form S-C (2): the regular train must not go beyond the point last named until the extra arrives.","SC · Form S-C");
Q("to","Form D, “No 1 has right over No 3 A to Z”, has no times. No 3 must not…",["Leave A ahead of No 1","Leave Z ahead of No 1","Run within 10 minutes of No 1","Take a siding between A and Z"],"Form D: if no time is given, the second-named train must not leave the first-named point ahead of the first-named train.","SC · Form D");
Q("to","“No 1 run 50 mins late A to G.” Other trains receiving this order…",["Run with respect to No 1's schedule 50 minutes later","May ignore No 1 between A and G","Must wait at A for No 1","Get right over No 1"],"Form E: time order.","SC · Form E");
Q("to","“Eng 99 extra A to F and return to C.” The extra…",["Must go to F before returning to C","May turn back at any point","Must stop at C first","Becomes a work extra"],"Form G (3).","SC · Form G");
Q("to","“Eng 292 works extra 6 45 am until 5 45 pm between D and E.” Within the limits the work extra must…",["Protect against extra trains in both directions and clear the time of regular trains","Protect only against regular trains","Need not protect against anyone","Protect against first-class trains only"],"Form S-H.","SC · Form S-H");
Q("to","A work extra order adds “Not protecting against eastward extra trains.” The work extra…",["Protects only against westward extras, and still clears regular trains' time","Protects against no one","Protects only against eastward extras","Need not clear the time of regular trains"],"Form S-H (a).","SC · Form S-H");
Q("to","An undelivered train order is to be annulled. The operator…",["Destroys all copies but his own and writes “Annulled by Order No __” on it","Delivers it marked “void”","Returns all copies to the dispatcher","Keeps them until the train arrives"],"Form L.","SC · Form L");
Q("to","May an annulled or superseded order be reissued under its original number?",["No","Yes, the same day","Yes, if the dispatcher initials it","Only for extras"],"Forms L and S-P.","SC · Forms L, S-P");
Q("to","Which words supersede an order or part of an order?",["“instead of”","“annulled”","“void”","“replacing order No”"],"Form S-P / P: “No 1 meet No 2 at C instead of B.”","SC · Form S-P");
Q("to","Under Rule 220, a part of a train order specifying a particular movement…",["May be either superseded or annulled","Can be changed only by annulling the whole order","Stays in effect until the train reaches its terminal","May be changed only by a new Clearance Form A"],"Rule 220: any part of an order specifying a particular movement may be either superseded or annulled.","SC · Rule 220");
Q("to","Form D: “Extra 62 east has right over No 4 Z to A and wait at Z until 12 50 p m…” Extra 62 east…",["Must not pass the designated stations before the time shown","May pass the designated stations early once No 4 has arrived","Must take the siding at each designated station","Must clear No 4's time at the designated stations"],"Form D: if train order time is given, the first-named train must not pass the designated stations before the time shown, and the second-named train must clear such times as required by rule.","SC · Form D");
Q("to","Order: “No 1 meet No 2 at B Second 4 at C and Extra 95 east at D.” Under Form S-A, this order…",["Fixes three meeting points in one order; the trains run with respect to each other to those points and meet as the rules prescribe","Is not a proper form; each meet needs its own order","Requires No 1 to take the siding at B, C and D","Gives No 1 right over the three trains from B to D"],"Form S-A (2) puts several meets in one order: “No 1 meet No 2 at B Second 4 at C and Extra 95 east at D (and so on).”","SC · Form S-A");
Q("to","The TT&TO primer describes another type of time order (Form E). It requires trains named to…",["Wait at certain points until a certain time","Run ahead of another train between two points","Display signals for a following section","Take the siding at every meeting point"],"TT&TO primer, Form E: another type of time order requires trains named to wait at certain points until a certain time.","TT · Forms");
Q("to","In the TT&TO primer's Form S-H explanation, the work extra must clear the main when on the time of…",["First class trains, with the specified safety margin","Extra trains in both directions","Eastward extra trains only","Second class trains only"],"TT&TO primer p19. The Standard Code Form S-H says the time of regular trains must be cleared.","TT · Forms");

Q("sig","Hand signal: swung at right angle to the track means…",["Stop","Proceed","Back","Reduced speed"],"Rule 12(a).","SC · Rule 12");
Q("sig","Hand signal: raised and lowered vertically means…",["Proceed","Stop","Back","Release brakes"],"Rule 12(c).","SC · Rule 12");
Q("sig","Hand signal: swung vertically in a circle at right angle to the track means…",["Back","Proceed","Stop","Apply air brakes"],"Rule 12(d).","SC · Rule 12");
Q("sig","Hand signal: held horizontally at arm's length means…",["Reduced speed","Stop","Proceed","Back"],"Rule 12(b).","SC · Rule 12");
Q("sig","Standard Code whistle — — (two long) means…",["Release brakes. Proceed.","Apply brakes. Stop.","Flagman protect rear","Approaching a crossing"],"Rule 14(b).","SC · Rule 14");
Q("sig","Standard Code whistle — o o o means…",["Flagman protect rear of train","Back up","Approaching a station","Release brakes, proceed"],"Rule 14(c).","SC · Rule 14");
Q("sig","Standard Code whistle: one short (o) means…",["Apply brakes. Stop.","Release brakes","Acknowledge","Back"],"Rule 14(a).","SC · Rule 14");
Q("sig","Whistle signal for approaching a public crossing at grade:",["— — o —","— o o o","o o o","— — —"],"Same in the Standard Code and GCOR.","SC · Rule 14(l) / GC · 5.8.2");
Q("sig","Standard Code: o o o when standing means…",["Back","Proceed","Flagman return","Apply brakes"],"Rule 14(h): when standing, back; the answer to hand signal 12(d).","SC · Rule 14(h)");
Q("sig","GCOR: crews on other trains hear a succession of short sounds. They must…",["Stop until it is safe to proceed","Acknowledge with o o","Continue at restricted speed","Sound the same signal"],"GCOR 5.8.2 (1): emergency warning.","GC · 5.8.2");
Q("sig","GCOR: at 45 MPH or less, the crossing whistle starts…",["At least 15 but not more than 20 seconds before the crossing","At the whistle post regardless of speed","1/4 mile before the crossing","10 seconds before the crossing"],"Over 45 MPH: at about the sign but not more than 1/4 mile before.","GC · 5.8.2(7)");
Q("sig","GCOR whistle — o means…",["Approaching men or equipment on or near the track","Release brakes","Flagman protect rear","Request a signal"],"Signal (8); then sound o o intermittently until past.","GC · 5.8.2");
Q("sig","The difference between a signal's aspect and its indication is…",["Aspect is what it looks like; indication is what it tells you","Aspect is the rule number; indication is the color","They mean the same","Aspect applies to semaphores only"],"Signals guide definitions; GCOR glossary agrees (indication = action required).","SG / GC · Glossary");
Q("sig","Which signaling system tells the engineer how fast to go past the signal?",["Speed signaling","Route signaling","APB","Interlocking"],"Speed signaling: eastern US and post-UCOR western roads. Most model railroads use route signaling.","SG");
Q("sig","In APB, when a train passes a head block signal at a siding…",["All opposing signals go to stop through to the head block at the next siding","The dispatcher must clear the next signal","Following signals go to stop for two blocks only","Nothing changes until the train reaches the next siding"],"Absolute Permissive Block.","SG");
Q("sig","A single green signal (route signaling, basic chart) indicates…",["Next two blocks are unoccupied","Next block is unoccupied","Proceed on the diverging route","Proceed at restricted speed"],"Clear.","SG · Signal chart");
Q("sig","Red over yellow on a two-head signal indicates…",["Diverging Approach","Stop","Approach","Restricting"],"“It's not red unless it's ALL red.”","SG · Route indications");
Q("sig","A signal with no plate shows stop. You must…",["Treat it as absolute: wait for permission","Stop, then proceed at restricted speed","Pass at restricted speed without stopping","Inspect the block"],"No plate is governed like an A plate.","SG · Signal signage");
Q("sig","A signal with a number plate shows stop. You may…",["Stop, then proceed at restricted speed","Not pass without the dispatcher's permission","Pass without stopping at track speed","Proceed after 5 minutes at track speed"],"A number plate marks a permissive signal: after stopping, proceed at restricted speed.","SG · Signal signage");
Q("sig","A G plate (with a number plate) lets a train…",["Pass the signal at restricted speed without stopping","Pass only with permission","Ignore the signal on an upgrade","Proceed at track speed"],"Grade signal, to keep trains from stalling on an upgrade.","SG · Signal signage");
Q("sig","A P plate on a signal means…",["A protective device in the block (e.g. slide or high water detector) the crew must inspect","The signal is permissive","A passenger station is ahead","Pilot required"],"Protective signal.","SG · Signal signage");
Q("sig","GCOR: crew members in the cab disagree on a signal's indication. They must…",["Regard it as the most restrictive indication observed","Follow the engineer's reading","Stop and call the dispatcher","Follow the conductor's reading"],"GCOR 1.47C.","GC · 1.47C");
Q("sig","Within a designated whistle quiet zone, signal (7) may be sounded approaching a public crossing when…",["The crew is notified the automatic warning devices are out of service","The train is moving faster than 45 MPH","The crossing has no crossing sign","The crossing gates are fully lowered"],"GCOR 5.8.4. Also in an emergency, when notified the devices are malfunctioning, or when the quiet zone is not in effect during specified hours.","GC · 5.8.4");
Q("sig","Other employees are working in the immediate area. Before moving, the crew must…",["Sound the required whistle signal","Get permission from the train dispatcher","Sound a succession of short sounds","Wait for a hand signal to proceed"],"GCOR 5.8.2. The whistle may also be used at anytime as a warning regardless of any whistle prohibitions.","GC · 5.8.2");
Q("sig","In typical CTC signal placement, trailing point signals are located…",["At the clearance point","Just clear of the switch points","Opposite each other","On a signal bridge, to the right of each track"],"Trailing point signals are at the clearance point; the facing point signal is just clear of the switch points.","SG · Signal placement");
Q("sig","In typical signal placement, an interlocking plant has a signal…",["For every track where it enters the interlocking limits","Only on the main track at each end of the plant","Only where a facing point switch is","Only on a signal bridge"],"Interlocking plants have a signal for every track where it enters the interlocking limits. If a signal bridge is used, signal heads are to the right of each track.","SG · Signal placement");

Q("sem","A semaphore blade in the horizontal position means…",["Stop","Approach","Clear","Depends on the quadrant"],"Horizontal is always stop.","SM");
Q("sem","An upper-quadrant semaphore's three positions are…",["0°, 45° and 90°","0°, 30° and 60°","0°, 60° and 90°","0°, 45° and 60°"],"Lower quadrant: 0°, 30°, 60°.","SM");
Q("sem","Why are lower-quadrant semaphores not inherently fail-safe?",["On failure, gravity drops the blade toward a proceed position","Their lamps burn out easily","They can only show two positions","The blade freezes in snow"],"A failure could turn stop into approach or clear.","SM");
Q("sem","What holds the colored roundels on a semaphore?",["The spectacle","The blade","The housing","The finial"],"Parts: blade, roundels, spectacle, lamp, actuating mechanism, housing.","SM");
Q("sem","Upper-quadrant semaphores came about around…",["1900","1840","1870","1930"],"The semaphore was patented in the 1840s; upper quadrant arrived around 1900.","SM");
Q("sem","In very early semaphores, a purple lens was sometimes used in lieu of…",["Red","Green","Yellow","White"],"Lens colors: Red, Purple (sometimes used in very early signals in lieu of red), Yellow, Green, and/or White (in very early signals before green lens was perfected).","SM · Forms");
Q("sem","Semaphore blade ends could be…",["Square, Round, Pointed, or Fishtail","Square or Round only","Pointed or Notched only","Fishtail only, on upper quadrant signals"],"The blades \"ends\" could be: Square, Round, Pointed, or Fishtail.","SM · Forms");
Q("sem","On a powered semaphore, the power unit/actuator is at…",["Either the base or top of the mast","The base of the mast only","The top of the mast only","A lineside case away from the mast"],"Powered semaphores can have the power unit/actuator at either the base or top of the mast.","SM · Forms");

Q("yl","Yard limits are a section of…",["Main track","Yard track","Siding","Industry track"],"Yard limits are main track.","YL");
Q("yl","Under Standard Code Rule 93, within yard limits the main track may be used clearing the time of…",["First-class trains at the next station where time is shown","All regular trains by 5 minutes","Extra trains","Trains of superior direction"],"Protection against ____ class (blank in the Code; second class in the TT&TO primer), extra trains and engines is not required.","SC · Rule 93");
Q("yl","Inside yard limits with no yardmaster or agent on duty, who is generally in charge?",["The conductor or switch crew foreman of the first train there","The dispatcher","The engineer of the longest train","Whoever arrives last"],"Yard Limits guide.","YL");
Q("yl","GCOR 6.13: movements within yard limits are made at restricted speed unless…",["Operating under a block signal indication more favorable than Approach","The main track is known to be clear","The yardmaster permits otherwise","The train is first class"],"GCOR 6.13.","GC · 6.13");
Q("yl","Yard limits in CTC territory (GCOR 6.13): who must authorize any main track movement?",["The control operator","The yardmaster","The conductor","No one; yard limits rules apply"],"GCOR 6.13.","GC · 6.13");
Q("yl","Why do railroads establish yard limits?",["So several crews can use short stretches of main track without the dispatcher issuing many orders","To raise speeds in yards","To keep extras off the main","To mark where train orders are delivered"],"Yard Limits guide.","YL");
Q("yl","Yard limits in Track Permit territory: which is NOT a way the control operator gives permission to enter the main track?",["The yardmaster authorizes the movement","A controlled signal displays a proceed indication","A track permit is issued","Verbal permission, if no track permit is in effect"],"GCOR 6.13: permission comes from the control operator by one of the other three.","GC · 6.13");
Q("yl","According to the Yard Limits guide, all movements within yard limits must be at…",["Restricted Speed, unless block signal protection is present","Track speed, since yard limits are main track","Whatever speed the yardmaster sets","Track speed, unless a train is known to be ahead"],"Yard Limits guide p2, item 5.","YL · Definitions");

Q("twc","A track warrant becomes effective when…",["The OK time is shown on it","The crew finishes copying it","The dispatcher reads the last box","The train passes the first named point"],"An authority without an OK time is just a piece of paper.","TW / GC · 14.9");
Q("twc","A warrant reads “Proceed from Anna to Bess” and Anna is the first named point. Authority at Anna begins at…",["The last siding switch at Anna, including it","The first siding switch at Anna","The station sign at Anna","The depot"],"First named point: from and includes the last siding switch. First is last.","GC · 14.2");
Q("twc","At the last named point, authority extends to…",["And includes the first siding switch","The station sign","And includes the last siding switch","The first siding switch, not including it"],"Last is first.","GC · 14.2");
Q("twc","Box 8, “Hold main track at last named point”, changes the limits so authority…",["Extends to but does not include the last siding switch","Ends at the first siding switch","Ends at the station sign","Extends to the next station"],"GCOR 14.2 Diagram B.","GC · 14.2");
Q("twc","A local needs to move in both directions between two points. Which box?",["Box 4, Work between","Box 2, Proceed from/to","Box 7, Not in effect until after arrival of","Box 10, Clear main track at last named point"],"Box 2 is one direction only.","TW · Authority");
Q("twc","Box 7 is…",["Not in effect until after arrival of __ at __","Hold main track at last named point","Do not foul limits ahead of __","This authority expires at __"],"Used in the worked example for 844 West waiting on 2211 East.","GC · 14.0 form");
Q("twc","Box 1 is…",["Track warrant no. __ is void","Proceed from __ to __","Work between __ and __","Other specific instructions"],"GCOR suggested form.","GC · 14.0 form");
Q("twc","Box 9 is…",["Do not foul limits ahead of __","Clear main track at last named point","Restricted speed, limits occupied by train","Not in effect until __"],"GCOR suggested form.","GC · 14.0 form");
Q("twc","Box 11 is…",["Between __ and __ make all movements at restricted speed. Limits occupied by train.","Do not exceed __ MPH","Flag protection not required against following trains","Track bulletins in effect"],"Box 12 is the same but for men or equipment.","GC · 14.0 form");
Q("twc","In the worked example, “joint with 1547 between ES Lori and Kara” goes in which box?",["17, Other specific instructions","11, Restricted speed","9, Do not foul limits ahead of","4, Work between"],"Box 17.","TW · Worked example");
Q("twc","A track warrant stays in effect until…",["The field employee releases it","The dispatcher's shift ends","The train reaches the last named point","Midnight"],"TWC selected rules.","TW · Selected rules");
Q("twc","To report clear of a warrant's limits outside yard limits, the train must be…",["Entirely clear of the limits and the main track, with switches restored to normal","Clear with the engine past the last named point","In a siding with the rear on the main","Stopped at the last named point"],"The entire train, not just the locomotive.","TW · Selected rules");
Q("twc","Do track warrants govern movement in sidings?",["No; only main track","Yes, always","Only when named in Box 17","Only in yard limits"],"Move in sidings at a speed allowing a stop within half the range of vision.","TW · Selected rules");
Q("twc","When copying a warrant, the employee repeats it to the dispatcher by reading…",["All the words on the form, not just box numbers and blanks","Only the box numbers checked","Only the limits","Only the OK time"],"TWC selected rules / GCOR 14.9.","TW / GC · 14.9");
Q("twc","GCOR 14.3: a train must not foul a switch at either end of its limits where…",["An opposing train may use it to clear the main track","There is no signal","The switch is hand-operated","The switch leads to an industry"],"GCOR 14.3.","GC · 14.3");
Q("twc","GCOR 14.9: who must each have a copy of the track warrant?",["The conductor and the engineer","Only the conductor","Only the engineer","The dispatcher and the operator"],"Each crew member must read and understand it; the copy shows the date.","GC · 14.9");
Q("twc","Except within yard limits, who may occupy the main track in TWC territory without authority?",["Nobody","Work extras","Trains under 20 MPH","Passenger trains"],"TWC selected rules.","TW");
Q("twc","A track warrant restricts movement that was previously authorized. When can the train dispatcher consider it in effect?",["When acknowledgment of the “OK” has been received","When the dispatcher says “OK” and gives the time","When the employee has written all the instructions on the form","When the train passes the first named point"],"GCOR 14.9 B(2). Any track warrant is not in effect until the “OK” time is shown on it.","GC · 14.9");
Q("twc","A track warrant is reproduced with a duplicating machine. Before it is delivered or used, it must be…",["Checked and verified as legible and duplicated in its entirety","Repeated to the train dispatcher","Given a new “OK” time","Relayed by radio to each crew member"],"GCOR 14.9.1: duplicated warrants do not need to be repeated to the train dispatcher.","GC · 14.9.1");
Q("twc","Per the TWC guide's selected rules, the OK that lets a track warrant be acted upon could be…",["OK time and initials, or just initials, or simply OK","A written copy handed up by an operator","Only the dispatcher's signature on the crew's copy","The warrant number repeated back by the crew"],"TWC guide p5: a track warrant may not be acted upon until the OK is received (could be OK time and initials, or just initials, or simply OK).","TW · Selected rules");
Q("twc","On the TWC guide's dispatcher record sheet, a straight line with an arrow pointing left or right shows…",["“Clear main track”","“Hold main track”","A warrant that has been voided","“Work between” two points"],"Arrow up or down is “hold main track”; arrow left or right is “clear main track”. The sheet is kept in pencil so authority can be erased when released.","TW · Dispatcher record");

Q("gcor","GCOR 6.27: the maximum speed when required to move at restricted speed is…",["20 MPH","15 MPH","10 MPH","25 MPH"],"Plus stopping within half the range of vision and watching for broken rail.","GC · 6.27");
Q("gcor","Restricted speed applies until…",["The leading wheels reach the point where it is no longer required","The rear of the train passes that point","The engineer sees a clear signal","The conductor gives permission"],"GCOR 6.27.","GC · 6.27");
Q("gcor","The conductor must remind the engineer of an approaching restriction (limits of authority, warrant, bulletin, radio speed restriction)…",["After passing the last station, but at least 2 miles before it","1 mile before it","When it comes into view","Only when asked"],"GCOR 1.47A(3).","GC · 1.47A");
Q("gcor","Two trains with conductors are combined. Who takes charge?",["The conductor with the most seniority","The conductor of the leading train","The engineer","The dispatcher decides"],"GCOR 1.47A(1).","GC · 1.47A");
Q("gcor","Where a yardmaster is on duty, train, engine and yard crews must…",["Comply with the yardmaster's instructions","Take instructions from the dispatcher only","Follow their conductor only","Work by timetable"],"GCOR 1.46.","GC · 1.46");
Q("gcor","After stopping for an unattended burning fusee, a train proceeds at restricted speed for…",["1 mile beyond the fusee","1/2 mile","2 miles","Until the next signal"],"A fusee beyond the first rail of an adjacent track does not apply.","GC · 5.6");
Q("gcor","GCOR 6.28: off the main track (and outside a block system), trains move at a speed allowing them to stop within…",["Half the range of vision","The range of vision","100 feet","One car length"],"GCOR 6.28.","GC · 6.28");
Q("gcor","An engine is stopped in a tunnel and cannot move promptly. The Rule 1.43 requirements do not apply when…",["Air currents carry the exhaust gases away from the train","The train is a passenger train","The train dispatcher has been notified","Hand brakes have been applied"],"GCOR 1.43 D. Safety of passengers and crew members must be the first consideration.","GC · 1.43");
